  v_scn  constant jsonb := $scn$[{"id": "P1 nothing", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [], "set": "status = 'COMPLETED'", "role": null, "want": "WARN:[\"NO_CASSANDRA_RECORD\", \"EVIDENCE_NOT_RECOGNIZED\"]@UPDATE:VERIFICATION>COMPLETED", "n": 1}, {"id": "P2 latest HOLD", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "HOLD", "stage": "FINAL"}]], "set": "status = 'COMPLETED'", "role": null, "want": "WARN:[\"LATEST_VERDICT_NOT_PASS\"]@UPDATE:VERIFICATION>COMPLETED", "n": 2}, {"id": "P3 PASS then FAIL", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "FAIL", "stage": "FINAL"}]], "set": "status = 'COMPLETED'", "role": null, "want": "WARN:[\"LATEST_VERDICT_NOT_PASS\"]@UPDATE:VERIFICATION>COMPLETED", "n": 3}, {"id": "P4 design pass only", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_DESIGN_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "DESIGN"}]], "set": "status = 'COMPLETED'", "role": null, "want": "REVIEW:[\"DESIGN_PASS_ONLY\"]@UPDATE:VERIFICATION>COMPLETED", "n": 4}, {"id": "P5 legacy NULL payload", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_VALIDATION", "CASSANDRA", null]], "set": "status = 'COMPLETED'", "role": null, "want": "REVIEW:[\"LATEST_VERDICT_UNSTRUCTURED\"]@UPDATE:VERIFICATION>COMPLETED", "n": 5}, {"id": "P6 requests are not evidence", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["VERIFICATION_REQUESTED", "캐스퍼", null], ["IMPLEMENTATION_REQUESTED", "마기", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}]], "set": "status = 'COMPLETED'", "role": null, "want": "REVIEW:[\"EVIDENCE_NOT_RECOGNIZED\"]@UPDATE:VERIFICATION>COMPLETED", "n": 6}, {"id": "P7 unknown verdict", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "MAYBE", "stage": "FINAL"}]], "set": "status = 'COMPLETED'", "role": null, "want": "WARN:[\"LATEST_VERDICT_NOT_PASS\"]@UPDATE:VERIFICATION>COMPLETED", "n": 7}, {"id": "P8 pass then unstructured", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}], ["CASSANDRA_VALIDATION", "CASSANDRA", {"audit": "x"}]], "set": "status = 'COMPLETED'", "role": null, "want": "REVIEW:[\"LATEST_VERDICT_UNSTRUCTURED\"]@UPDATE:VERIFICATION>COMPLETED", "n": 8}, {"id": "P9 verifier is not evidence", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}]], "set": "status = 'COMPLETED'", "role": null, "want": "REVIEW:[\"EVIDENCE_NOT_RECOGNIZED\"]@UPDATE:VERIFICATION>COMPLETED", "n": 9}, {"id": "P10 stage missing", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS"}]], "set": "status = 'COMPLETED'", "role": null, "want": "REVIEW:[\"PASS_STAGE_NOT_FINAL\"]@UPDATE:VERIFICATION>COMPLETED", "n": 10}, {"id": "P11 secondary never lowers HARD", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["MAGI_DECISION", "마기", {"verdict": "PASS", "stage": "FINAL", "verifier_role": "SECONDARY", "tier": "LOW"}]], "set": "status = 'COMPLETED'", "role": null, "want": "WARN:[\"NO_CASSANDRA_RECORD\"]@UPDATE:VERIFICATION>COMPLETED", "n": 11}, {"id": "P12 PASS by other actor ignored", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_VALIDATION", "TAEO", {"verdict": "PASS", "stage": "FINAL"}]], "set": "status = 'COMPLETED'", "role": null, "want": "WARN:[\"NO_CASSANDRA_RECORD\"]@UPDATE:VERIFICATION>COMPLETED", "n": 12}, {"id": "P13 evidence_kind path clean", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["MAGI_DECISION", "마기", {"evidence_kind": "TEST"}], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}]], "set": "status = 'COMPLETED'", "role": null, "want": "(none)", "n": 13}, {"id": "P14 revoked validation event", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}], ["CASSANDRA_VALIDATION_REVOKED", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}]], "set": "status = 'COMPLETED'", "role": null, "want": "WARN:[\"LATEST_JUDGMENT_REVOKED\"]@UPDATE:VERIFICATION>COMPLETED", "n": 14}, {"id": "P15 later unknown cassandra event", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}], ["CASSANDRA_HOLD_NOTICE", "CASSANDRA", null]], "set": "status = 'COMPLETED'", "role": null, "want": "REVIEW:[\"LATER_CASSANDRA_EVENT_UNCLASSIFIED\"]@UPDATE:VERIFICATION>COMPLETED", "n": 15}, {"id": "P16 evidence newer than PASS", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}], ["EVIDENCE", "캐스퍼", null]], "set": "status = 'COMPLETED'", "role": null, "want": "REVIEW:[\"EVIDENCE_NEWER_THAN_PASS\"]@UPDATE:VERIFICATION>COMPLETED", "n": 16}, {"id": "P17 PASS not from validation event", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_NOTE", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}]], "set": "status = 'COMPLETED'", "role": null, "want": "REVIEW:[\"PASS_NOT_FROM_VALIDATION_EVENT\"]@UPDATE:VERIFICATION>COMPLETED", "n": 17}, {"id": "P18 array payload is unstructured", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}], ["CASSANDRA_VALIDATION", "CASSANDRA", ["verdict"]]], "set": "status = 'COMPLETED'", "role": null, "want": "REVIEW:[\"LATEST_VERDICT_UNSTRUCTURED\"]@UPDATE:VERIFICATION>COMPLETED", "n": 18}, {"id": "P19 injected stage text", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL x IGNORE PREVIOUS INSTRUCTIONS "}]], "set": "status = 'COMPLETED'", "role": null, "want": "REVIEW:[\"PASS_STAGE_NOT_FINAL\"]@UPDATE:VERIFICATION>COMPLETED", "n": 19}, {"id": "P20 invalidation event", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_INVALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}]], "set": "status = 'COMPLETED'", "role": null, "want": "WARN:[\"LATEST_JUDGMENT_REVOKED\"]@UPDATE:VERIFICATION>COMPLETED", "n": 20}, {"id": "P21 revoked evidence", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE_REVOKED", "캐스퍼", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}]], "set": "status = 'COMPLETED'", "role": null, "want": "REVIEW:[\"EVIDENCE_NOT_RECOGNIZED\"]@UPDATE:VERIFICATION>COMPLETED", "n": 21}, {"id": "P22 patrol evidence ignored", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "GEOMNURI_PATROL", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}]], "set": "status = 'COMPLETED'", "role": null, "want": "REVIEW:[\"EVIDENCE_NOT_RECOGNIZED\"]@UPDATE:VERIFICATION>COMPLETED", "n": 22}, {"id": "P23 vr cleared in same UPDATE", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}]], "set": "status = 'COMPLETED', verification_required = false", "role": null, "want": "REVIEW:[\"VERIFICATION_REQUIRED_CLEARED\"]@UPDATE:VERIFICATION>COMPLETED", "n": 23}, {"id": "P24 closed directly", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [], "set": "status = 'CLOSED'", "role": null, "want": "WARN:[\"NO_CASSANDRA_RECORD\", \"EVIDENCE_NOT_RECOGNIZED\"]@UPDATE:VERIFICATION>CLOSED", "n": 24}, {"id": "P25 PASS from non-allowlisted validation-like type", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_PRE_VALIDATION_NOTE", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}]], "set": "status = 'COMPLETED'", "role": null, "want": "REVIEW:[\"PASS_NOT_FROM_VALIDATION_EVENT\"]@UPDATE:VERIFICATION>COMPLETED", "n": 25}, {"id": "P26 evidence written by CASSANDRA is not independent", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "CASSANDRA", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}]], "set": "status = 'COMPLETED'", "role": null, "want": "REVIEW:[\"EVIDENCE_NOT_RECOGNIZED\"]@UPDATE:VERIFICATION>COMPLETED", "n": 26}, {"id": "N1 evidence + PASS/FINAL", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}]], "set": "status = 'COMPLETED'", "role": null, "want": "(none)", "n": 27}, {"id": "N2 latest wins after HOLD", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "HOLD", "stage": "FINAL"}], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}]], "set": "status = 'COMPLETED'", "role": null, "want": "(none)", "n": 28}, {"id": "N3 vr false", "mode": "update", "vr": false, "start": "VERIFICATION", "events": [], "set": "status = 'COMPLETED'", "role": null, "want": "(none)", "n": 29}, {"id": "N4 title-only update", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [], "set": "title = 'rehearsal title only'", "role": null, "want": "(none)", "n": 30}, {"id": "N5 agreement event is neutral", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}], ["AGREEMENT_RESPONSE", "CASSANDRA", {"agreement": "CONDITIONAL_AGREE"}]], "set": "status = 'COMPLETED'", "role": null, "want": "(none)", "n": 31}, {"id": "N6 operational guidance neutral", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}], ["CASSANDRA_OPERATIONAL_GUIDANCE", "CASSANDRA", null]], "set": "status = 'COMPLETED'", "role": null, "want": "(none)", "n": 32}, {"id": "N7 non-completing status update", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [], "set": "status = 'REVIEW'", "role": null, "want": "(none)", "n": 33}, {"id": "A1 anon update, violation recorded", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [], "set": "status = 'COMPLETED'", "role": "anon", "want": "WARN:[\"NO_CASSANDRA_RECORD\", \"EVIDENCE_NOT_RECOGNIZED\"]@UPDATE:VERIFICATION>COMPLETED", "n": 34}, {"id": "A2 anon update, clean", "mode": "update", "vr": true, "start": "VERIFICATION", "events": [["EVIDENCE", "캐스퍼", null], ["CASSANDRA_VALIDATION", "CASSANDRA", {"verdict": "PASS", "stage": "FINAL"}]], "set": "status = 'COMPLETED'", "role": "anon", "want": "(none)", "n": 35}, {"id": "I1 insert COMPLETED vr", "mode": "insert", "vr": true, "start": "COMPLETED", "events": [], "set": "", "role": null, "want": "WARN:[\"NO_CASSANDRA_RECORD\", \"EVIDENCE_NOT_RECOGNIZED\"]@INSERT:null>COMPLETED", "n": 36}, {"id": "I2 insert CLOSED vr", "mode": "insert", "vr": true, "start": "CLOSED", "events": [], "set": "", "role": null, "want": "WARN:[\"NO_CASSANDRA_RECORD\", \"EVIDENCE_NOT_RECOGNIZED\"]@INSERT:null>CLOSED", "n": 37}, {"id": "I3 insert COMPLETED no vr", "mode": "insert", "vr": false, "start": "COMPLETED", "events": [], "set": "", "role": null, "want": "(none)", "n": 38}, {"id": "I4 insert VERIFICATION vr", "mode": "insert", "vr": true, "start": "VERIFICATION", "events": [], "set": "", "role": null, "want": "(none)", "n": 39}]$scn$::jsonb;
  v_rep_want constant jsonb := $scn${"25": "WARN:[\"NO_CASSANDRA_RECORD\", \"EVIDENCE_NOT_RECOGNIZED\"]@UPDATE:VERIFICATION>COMPLETED", "145": "WARN:[\"NO_CASSANDRA_RECORD\", \"EVIDENCE_NOT_RECOGNIZED\"]@UPDATE:VERIFICATION>COMPLETED", "147": "WARN:[\"NO_CASSANDRA_RECORD\", \"EVIDENCE_NOT_RECOGNIZED\"]@UPDATE:VERIFICATION>COMPLETED", "160": "REVIEW:[\"LATEST_VERDICT_UNSTRUCTURED\"]@UPDATE:VERIFICATION>COMPLETED", "174": "REVIEW:[\"LATEST_VERDICT_UNSTRUCTURED\"]@UPDATE:VERIFICATION>COMPLETED", "83": "REVIEW:[\"LATEST_VERDICT_UNSTRUCTURED\", \"EVIDENCE_NOT_RECOGNIZED\"]@UPDATE:VERIFICATION>COMPLETED", "157": "REVIEW:[\"LATEST_VERDICT_UNSTRUCTURED\", \"EVIDENCE_NOT_RECOGNIZED\"]@UPDATE:VERIFICATION>COMPLETED", "164": "REVIEW:[\"LATEST_VERDICT_UNSTRUCTURED\", \"EVIDENCE_NOT_RECOGNIZED\"]@UPDATE:VERIFICATION>COMPLETED", "167": "REVIEW:[\"LATEST_VERDICT_UNSTRUCTURED\", \"EVIDENCE_NOT_RECOGNIZED\"]@UPDATE:VERIFICATION>COMPLETED", "170": "REVIEW:[\"LATEST_VERDICT_UNSTRUCTURED\", \"EVIDENCE_NOT_RECOGNIZED\"]@UPDATE:VERIFICATION>COMPLETED", "171": "REVIEW:[\"LATEST_VERDICT_UNSTRUCTURED\", \"EVIDENCE_NOT_RECOGNIZED\"]@UPDATE:VERIFICATION>COMPLETED", "172": "REVIEW:[\"LATEST_VERDICT_UNSTRUCTURED\", \"EVIDENCE_NOT_RECOGNIZED\"]@UPDATE:VERIFICATION>COMPLETED", "175": "REVIEW:[\"LATEST_VERDICT_UNSTRUCTURED\", \"EVIDENCE_NOT_RECOGNIZED\"]@UPDATE:VERIFICATION>COMPLETED"}$scn$::jsonb;
  v_rep_tasks constant int[] := array[25, 145, 147, 160, 174, 83, 157, 164, 167, 170, 171, 172, 175, 194, 204, 205];
  v_t0 timestamptz := clock_timestamp(); v_lock_at timestamptz; v_hold_ms numeric; v_total_ms numeric;
  v_log text[] := '{}'; v_fail text[] := '{}'; v_drift text[] := '{}'; v_info text[] := '{}';
  n_ok int := 0; n_bad int := 0; n_scn int := 0; n_scn_ok int := 0; n_rep_ok int := 0; n_rep_drift int := 0;
  v_fatal text := ''; v_id text; v_got text; v_want text; v_n int; v_m int; v_tid bigint; v_eid bigint;
  s jsonb; e jsonb; t_id int; v_a timestamptz; v_upd_max numeric := 0; v_ms numeric;
  v_seq0 bigint; v_seq1 bigint; v_fn_md5 text; v_trg0 text; v_trg1 text; v_etrg0 text; v_etrg1 text; v_mut text; v_proc0 int; v_proc1 int;
begin
  -- ---------- G: guards, all read-only, abort BEFORE any DDL ----------
  if current_setting('transaction_read_only') <> 'off' then raise exception 'REHEARSAL_ABORTED_BEFORE_DDL: transaction is read only'; end if;
  if not pg_has_role(current_user, 'anon', 'member') then raise exception 'REHEARSAL_ABORTED_BEFORE_DDL: current_user % cannot SET ROLE anon', current_user; end if;
  if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'fn_completion_gate_observe')
     or exists (select 1 from pg_trigger where tgname like '%completion_gate%' and not tgisinternal) then
    raise exception 'REHEARSAL_ABORTED_BEFORE_DDL: gate objects already exist (not a first-time rehearsal)'; end if;
  if not (select c.relrowsecurity and not c.relforcerowsecurity and pg_get_userbyid(c.relowner) = current_user from pg_class c where c.oid = 'public.magi_tasks'::regclass)
     or not (select c.relrowsecurity and not c.relforcerowsecurity and pg_get_userbyid(c.relowner) = current_user from pg_class c where c.oid = 'public.magi_task_events'::regclass) then
    raise exception 'REHEARSAL_ABORTED_BEFORE_DDL: table ownership/RLS differs from the measured production facts'; end if;
  select count(*) into v_n from pg_stat_activity where pid <> pg_backend_pid() and datname = current_database()
    and xact_start is not null and now() - xact_start > interval '10 seconds' and state <> 'idle';
  if v_n > 0 then raise exception 'REHEARSAL_ABORTED_BEFORE_DDL: % session(s) hold a transaction older than 10 s (lock queue risk)', v_n; end if;
  -- bounded lock wait: never queue behind a busy table for long.  (statement_timeout cannot be tightened from inside a running
  -- statement; the run is bounded by the session's own statement_timeout, and by its measured length of well under a second.)
  perform set_config('lock_timeout', '1500ms', true);
  select last_value into v_seq0 from pg_sequences where schemaname = 'public' and sequencename = 'magi_task_events_event_id_seq';
  select count(*) into v_proc0 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public';
  v_trg0 := (select string_agg(pg_get_triggerdef(t.oid), E'\n' order by t.tgname) from pg_trigger t where t.tgrelid = 'public.magi_tasks'::regclass and not t.tgisinternal and t.tgname !~ 'completion_gate'); v_etrg0 := (select string_agg(pg_get_triggerdef(t.oid), E'\n' order by t.tgname) from pg_trigger t where t.tgrelid = 'public.magi_task_events'::regclass and not t.tgisinternal and t.tgname !~ 'completion_gate');
  v_info := v_info || ('pg=' || current_setting('server_version') || ' role=' || current_user);

  begin   -- inner block: any failure below is recorded, then the final RAISE still rolls everything back
    -- single lock point; ACCESS EXCLUSIVE is what DROP TRIGGER IF EXISTS takes anyway
    -- the lock is requested BEFORE this transaction reads magi_tasks, so it never asks to upgrade a weaker lock it already holds
    -- (an upgrade queue can make concurrent writers wait a full deadlock_timeout)
    lock table public.magi_tasks in access exclusive mode;
    v_lock_at := clock_timestamp();
    if exists (select 1 from public.magi_tasks where task_id >= c_task_base) or exists (select 1 from public.magi_task_events where event_id >= c_evt_base) then
      raise exception 'REHEARSAL_ABORTED_BEFORE_DDL: fixture id range is occupied'; end if;

    -- ---------- D: DDL of docs section 5 ----------
    execute v_gate;
    v_id := 'D1 function exists once'; v_got := ((select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='fn_completion_gate_observe'))::text; v_want := (1)::text;
  if v_got is not distinct from v_want then n_ok := n_ok + 1; v_log := v_log || (v_id || ':ok');
  else n_bad := n_bad + 1; v_log := v_log || (v_id || ':FAIL');
    v_fail := v_fail || (v_id || ' got=' || coalesce(left(v_got, 300), '<null>') || ' want=' || coalesce(left(v_want, 300), '<null>')); end if;
    v_id := 'D2 owner/secdef/search_path'; v_got := ((select pg_get_userbyid(proowner) = current_user and prosecdef and proconfig::text = '{"search_path=pg_catalog, public, pg_temp"}' from pg_proc where oid = 'public.fn_completion_gate_observe()'::regprocedure))::text; v_want := (true)::text;
  if v_got is not distinct from v_want then n_ok := n_ok + 1; v_log := v_log || (v_id || ':ok');
  else n_bad := n_bad + 1; v_log := v_log || (v_id || ':FAIL');
    v_fail := v_fail || (v_id || ' got=' || coalesce(left(v_got, 300), '<null>') || ' want=' || coalesce(left(v_want, 300), '<null>')); end if;
    v_id := 'D3 anon/authenticated/public cannot execute'; v_got := ((select not has_function_privilege('anon', oid, 'execute') and not has_function_privilege('authenticated', oid, 'execute') and not exists (select 1 from aclexplode(proacl) x where x.grantee = 0) from pg_proc where oid = 'public.fn_completion_gate_observe()'::regprocedure))::text; v_want := (true)::text;
  if v_got is not distinct from v_want then n_ok := n_ok + 1; v_log := v_log || (v_id || ':ok');
  else n_bad := n_bad + 1; v_log := v_log || (v_id || ':FAIL');
    v_fail := v_fail || (v_id || ' got=' || coalesce(left(v_got, 300), '<null>') || ' want=' || coalesce(left(v_want, 300), '<null>')); end if;
    v_id := 'D4 four triggers on magi_tasks, all enabled'; v_got := ((select string_agg(tgname || ':' || tgenabled::text, ',' order by tgname) from pg_trigger where tgrelid = 'public.magi_tasks'::regclass and not tgisinternal))::text; v_want := ('trg_magi_tasks_completion_gate_observe:O,trg_magi_tasks_completion_gate_observe_ins:O,trg_magi_tasks_delete_log:O,trg_require_magi_task_domain_on_insert:O')::text;
  if v_got is not distinct from v_want then n_ok := n_ok + 1; v_log := v_log || (v_id || ':ok');
  else n_bad := n_bad + 1; v_log := v_log || (v_id || ':FAIL');
    v_fail := v_fail || (v_id || ' got=' || coalesce(left(v_got, 300), '<null>') || ' want=' || coalesce(left(v_want, 300), '<null>')); end if;
    v_id := 'D5 existing triggers untouched'; v_got := (((select string_agg(pg_get_triggerdef(t.oid), E'\n' order by t.tgname) from pg_trigger t where t.tgrelid = 'public.magi_tasks'::regclass and not t.tgisinternal and t.tgname !~ 'completion_gate') = v_trg0 and (select string_agg(pg_get_triggerdef(t.oid), E'\n' order by t.tgname) from pg_trigger t where t.tgrelid = 'public.magi_task_events'::regclass and not t.tgisinternal and t.tgname !~ 'completion_gate') = v_etrg0))::text; v_want := (true)::text;
  if v_got is not distinct from v_want then n_ok := n_ok + 1; v_log := v_log || (v_id || ':ok');
  else n_bad := n_bad + 1; v_log := v_log || (v_id || ':FAIL');
    v_fail := v_fail || (v_id || ' got=' || coalesce(left(v_got, 300), '<null>') || ' want=' || coalesce(left(v_want, 300), '<null>')); end if;
    v_id := 'D6 gate function is the only new public function'; v_got := ((select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public') - v_proc0)::text; v_want := (1)::text;
  if v_got is not distinct from v_want then n_ok := n_ok + 1; v_log := v_log || (v_id || ':ok');
  else n_bad := n_bad + 1; v_log := v_log || (v_id || ':FAIL');
    v_fail := v_fail || (v_id || ' got=' || coalesce(left(v_got, 300), '<null>') || ' want=' || coalesce(left(v_want, 300), '<null>')); end if;
    v_fn_md5 := md5(pg_get_functiondef('public.fn_completion_gate_observe()'::regprocedure));
    execute v_gate;   -- re-run: create/drop trigger must be repeatable
    v_id := 'D7 DDL is re-runnable, same function body'; v_got := (md5(pg_get_functiondef('public.fn_completion_gate_observe()'::regprocedure)) = v_fn_md5 and (select count(*) from pg_trigger where tgrelid = 'public.magi_tasks'::regclass and tgname like '%completion_gate%') = 2)::text; v_want := (true)::text;
  if v_got is not distinct from v_want then n_ok := n_ok + 1; v_log := v_log || (v_id || ':ok');
  else n_bad := n_bad + 1; v_log := v_log || (v_id || ':FAIL');
    v_fail := v_fail || (v_id || ' got=' || coalesce(left(v_got, 300), '<null>') || ' want=' || coalesce(left(v_want, 300), '<null>')); end if;

    -- ---------- scenarios: fixture tasks and events with explicit high ids (identity ALWAYS => OVERRIDING SYSTEM VALUE) ----------
    for s in select value from jsonb_array_elements(v_scn) loop
      v_tid := c_task_base + (s->>'n')::int; v_eid := c_evt_base + (s->>'n')::bigint * 1000; n_scn := n_scn + 1;
      insert into public.magi_tasks(task_id, title, owner_agent, status, priority, verification_required, domain) overriding system value
        values (v_tid, 'rehearsal ' || (s->>'id'), 'REHEARSAL', s->>'start', 'P1', (s->>'vr')::boolean, 'magi');
      for e in select value from jsonb_array_elements(s->'events') loop
        v_eid := v_eid + 1;
        insert into public.magi_task_events(event_id, task_id, event_type, actor, detail, payload) overriding system value
          values (v_eid, v_tid, e->>0, e->>1, 'rehearsal', case when jsonb_typeof(e->2) = 'null' then null else e->2 end);
      end loop;
      if s->>'mode' = 'update' then
        v_a := clock_timestamp();
        if s->>'role' is not null then execute 'set local role ' || quote_ident(s->>'role'); end if;
        execute 'update public.magi_tasks set ' || (s->>'set') || ' where task_id = ' || v_tid;
        execute 'reset role';
        v_ms := extract(epoch from clock_timestamp() - v_a) * 1000; if v_ms > v_upd_max then v_upd_max := v_ms; end if;
      end if;
            v_id := s->>'id'; v_got := (select coalesce(string_agg((payload->>'gate_level') || ':' || (payload->'reasons')::text || '@' || (payload->>'op') || ':' || coalesce(payload->>'from_status', 'null') || '>' || (payload->>'to_status'), ' | ' order by event_id), '(none)') from public.magi_task_events where task_id = v_tid and event_type = 'COMPLETION_GATE_VIOLATION'); v_want := s->>'want';
      if v_got is not distinct from v_want then n_ok := n_ok + 1; v_log := v_log || (v_id || ':ok'); n_scn_ok := n_scn_ok + 1;
      else n_bad := n_bad + 1; v_log := v_log || (v_id || ':FAIL');
        v_fail := v_fail || (v_id || ' got=' || coalesce(left(v_got, 300), '<null>') || ' want=' || coalesce(left(v_want, 300), '<null>')); end if;
    end loop;
    -- N8: COMPLETED -> CLOSED must not fire again; reopening and completing again fires once more
    v_tid := c_task_base + 990;
    insert into public.magi_tasks(task_id, title, owner_agent, status, priority, verification_required, domain) overriding system value values (v_tid, 'rehearsal N8', 'REHEARSAL', 'VERIFICATION', 'P1', true, 'magi');
    update public.magi_tasks set status = 'COMPLETED' where task_id = v_tid;
    update public.magi_tasks set status = 'CLOSED' where task_id = v_tid;
    select count(*) into v_n from public.magi_task_events where task_id = v_tid and event_type = 'COMPLETION_GATE_VIOLATION';
    update public.magi_tasks set status = 'IN_PROGRESS' where task_id = v_tid;
    update public.magi_tasks set status = 'COMPLETED' where task_id = v_tid;
    select count(*) into v_m from public.magi_task_events where task_id = v_tid and event_type = 'COMPLETION_GATE_VIOLATION';
    v_id := 'N8 COMPLETED->CLOSED not re-fired; reopen+complete fires again'; v_got := (v_n || ',' || v_m)::text; v_want := ('1,2')::text;
  if v_got is not distinct from v_want then n_ok := n_ok + 1; v_log := v_log || (v_id || ':ok');
  else n_bad := n_bad + 1; v_log := v_log || (v_id || ':FAIL');
    v_fail := v_fail || (v_id || ' got=' || coalesce(left(v_got, 300), '<null>') || ' want=' || coalesce(left(v_want, 300), '<null>')); end if;

    -- A3: anon cannot call the SECURITY DEFINER function directly
    begin
      execute 'set local role anon'; perform public.fn_completion_gate_observe(); v_got := 'EXECUTED';
    exception when insufficient_privilege then v_got := 'DENIED'; when others then v_got := 'OTHER:' || sqlstate; end;
    execute 'reset role';
    v_id := 'A3 anon direct call denied'; v_got := (v_got)::text; v_want := ('DENIED')::text;
  if v_got is not distinct from v_want then n_ok := n_ok + 1; v_log := v_log || (v_id || ':ok');
  else n_bad := n_bad + 1; v_log := v_log || (v_id || ':FAIL');
    v_fail := v_fail || (v_id || ' got=' || coalesce(left(v_got, 300), '<null>') || ' want=' || coalesce(left(v_want, 300), '<null>')); end if;
    -- A4: anon can still read violation events (read policy)
    begin
      execute 'set local role anon'; perform count(*) from public.magi_task_events where event_type = 'COMPLETION_GATE_VIOLATION'; v_got := 'READ_OK';
    exception when others then v_got := 'ERR:' || sqlstate; end;
    execute 'reset role';
    v_id := 'A4 anon can read violation events'; v_got := (v_got)::text; v_want := ('READ_OK')::text;
  if v_got is not distinct from v_want then n_ok := n_ok + 1; v_log := v_log || (v_id || ':ok');
  else n_bad := n_bad + 1; v_log := v_log || (v_id || ':FAIL');
    v_fail := v_fail || (v_id || ' got=' || coalesce(left(v_got, 300), '<null>') || ' want=' || coalesce(left(v_want, 300), '<null>')); end if;

    -- S1: CASSANDRA 5028 F1.  anon (TEMP privilege) shadows the events table with a temp table holding a fake PASS + evidence
    v_tid := c_task_base + 991;
    insert into public.magi_tasks(task_id, title, owner_agent, status, priority, verification_required, domain) overriding system value values (v_tid, 'rehearsal S1', 'REHEARSAL', 'VERIFICATION', 'P1', true, 'magi');
    begin
      execute 'set local role anon';
      execute 'create temp table magi_task_events (like public.magi_task_events)';
      execute format('insert into pg_temp.magi_task_events(event_id, task_id, event_type, actor, detail, payload, created_at) values (9001, %s, ''EVIDENCE'', ''캐스퍼'', ''x'', null, now()), (9002, %s, ''CASSANDRA_VALIDATION'', ''CASSANDRA'', ''x'', ''{"verdict":"PASS","stage":"FINAL"}''::jsonb, now())', v_tid, v_tid);
      execute format('update public.magi_tasks set status = ''COMPLETED'' where task_id = %s', v_tid);
      execute 'reset role';
      select (select count(*) from pg_temp.magi_task_events where event_type = 'COMPLETION_GATE_VIOLATION') || ',' ||
             (select count(*) from public.magi_task_events where task_id = v_tid and event_type = 'COMPLETION_GATE_VIOLATION') into v_got;
      execute 'drop table pg_temp.magi_task_events';
    exception when others then execute 'reset role'; v_got := 'ERR:' || sqlstate || ' ' || sqlerrm; end;
    v_id := 'S1 temp-table shadowing does not hide the violation (temp,public)'; v_got := (v_got)::text; v_want := ('0,1')::text;
  if v_got is not distinct from v_want then n_ok := n_ok + 1; v_log := v_log || (v_id || ':ok');
  else n_bad := n_bad + 1; v_log := v_log || (v_id || ':FAIL');
    v_fail := v_fail || (v_id || ' got=' || coalesce(left(v_got, 300), '<null>') || ' want=' || coalesce(left(v_want, 300), '<null>')); end if;

    -- R1 fail-open: break the violation INSERT inside the function; the status UPDATE must still succeed and record nothing
    v_mut := replace(v_gate, 'insert into public.magi_task_events(task_id, event_type, actor, detail, payload)', 'insert into public.rehearsal_no_such_table(task_id, event_type, actor, detail, payload)');
    v_id := 'R1a mutation was applied to the test variant'; v_got := (v_mut <> v_gate)::text; v_want := (true)::text;
  if v_got is not distinct from v_want then n_ok := n_ok + 1; v_log := v_log || (v_id || ':ok');
  else n_bad := n_bad + 1; v_log := v_log || (v_id || ':FAIL');
    v_fail := v_fail || (v_id || ' got=' || coalesce(left(v_got, 300), '<null>') || ' want=' || coalesce(left(v_want, 300), '<null>')); end if;
    execute v_mut;
    v_tid := c_task_base + 992;
    insert into public.magi_tasks(task_id, title, owner_agent, status, priority, verification_required, domain) overriding system value values (v_tid, 'rehearsal R1', 'REHEARSAL', 'VERIFICATION', 'P1', true, 'magi');
    update public.magi_tasks set status = 'COMPLETED' where task_id = v_tid;
    select status || ',' || (select count(*) from public.magi_task_events where task_id = v_tid and event_type = 'COMPLETION_GATE_VIOLATION') into v_got from public.magi_tasks where task_id = v_tid;
    v_id := 'R1 UPDATE succeeds when the gate function fails (fail-open)'; v_got := (v_got)::text; v_want := ('COMPLETED,0')::text;
  if v_got is not distinct from v_want then n_ok := n_ok + 1; v_log := v_log || (v_id || ':ok');
  else n_bad := n_bad + 1; v_log := v_log || (v_id || ':FAIL');
    v_fail := v_fail || (v_id || ' got=' || coalesce(left(v_got, 300), '<null>') || ' want=' || coalesce(left(v_want, 300), '<null>')); end if;
    execute v_gate;   -- restore the real function
    v_id := 'R1b real function restored'; v_got := (md5(pg_get_functiondef('public.fn_completion_gate_observe()'::regprocedure)))::text; v_want := (v_fn_md5)::text;
  if v_got is not distinct from v_want then n_ok := n_ok + 1; v_log := v_log || (v_id || ':ok');
  else n_bad := n_bad + 1; v_log := v_log || (v_id || ':FAIL');
    v_fail := v_fail || (v_id || ' got=' || coalesce(left(v_got, 300), '<null>') || ' want=' || coalesce(left(v_want, 300), '<null>')); end if;

    -- G-checks over everything this run produced
    v_id := 'R3 violation events carry no patrol trigger keys or markers'; v_got := ((select count(*) from public.magi_task_events where event_type = 'COMPLETION_GATE_VIOLATION' and (payload ? 'severity' or payload ? 'level' or payload ? 'priority' or detail ~ '🔴|\[CRITICAL\]|P0 |P1 |P0급|P0격상')))::text; v_want := (0)::text;
  if v_got is not distinct from v_want then n_ok := n_ok + 1; v_log := v_log || (v_id || ':ok');
  else n_bad := n_bad + 1; v_log := v_log || (v_id || ':FAIL');
    v_fail := v_fail || (v_id || ' got=' || coalesce(left(v_got, 300), '<null>') || ' want=' || coalesce(left(v_want, 300), '<null>')); end if;
    v_id := 'O1 copied verdict/stage/tier tokens are sanitized'; v_got := ((select count(*) from public.magi_task_events where event_type = 'COMPLETION_GATE_VIOLATION' and ((payload->>'last_verdict') !~ '^[A-Z0-9_]{1,32}$' or (payload->>'last_stage') !~ '^[A-Z0-9_]{1,32}$' or (payload->>'tier_recorded') !~ '^[A-Z0-9_]{1,32}$')))::text; v_want := (0)::text;
  if v_got is not distinct from v_want then n_ok := n_ok + 1; v_log := v_log || (v_id || ':ok');
  else n_bad := n_bad + 1; v_log := v_log || (v_id || ':FAIL');
    v_fail := v_fail || (v_id || ' got=' || coalesce(left(v_got, 300), '<null>') || ' want=' || coalesce(left(v_want, 300), '<null>')); end if;
    v_id := 'O2 no violation event outside the fixture task range'; v_got := ((select count(*) from public.magi_task_events where event_type = 'COMPLETION_GATE_VIOLATION' and task_id < c_task_base))::text; v_want := (0)::text;
  if v_got is not distinct from v_want then n_ok := n_ok + 1; v_log := v_log || (v_id || ':ok');
  else n_bad := n_bad + 1; v_log := v_log || (v_id || ':FAIL');
    v_fail := v_fail || (v_id || ' got=' || coalesce(left(v_got, 300), '<null>') || ' want=' || coalesce(left(v_want, 300), '<null>')); end if;
    v_id := 'O3 violation events are attributed to COMPLETION_GATE with domain inherited'; v_got := ((select count(*) from public.magi_task_events where event_type = 'COMPLETION_GATE_VIOLATION' and (actor <> 'COMPLETION_GATE' or domain is distinct from 'magi')))::text; v_want := (0)::text;
  if v_got is not distinct from v_want then n_ok := n_ok + 1; v_log := v_log || (v_id || ':ok');
  else n_bad := n_bad + 1; v_log := v_log || (v_id || ':FAIL');
    v_fail := v_fail || (v_id || ' got=' || coalesce(left(v_got, 300), '<null>') || ' want=' || coalesce(left(v_want, 300), '<null>')); end if;

    -- ---------- replay of REAL production histories (read from magi_task_events, copied to fixture tasks, then completed) ----------
    foreach t_id in array v_rep_tasks loop
      v_tid := c_task_base + 100000 + t_id;
      select count(*) into v_n from public.magi_task_events where task_id = t_id and event_id < c_evt_base;
      insert into public.magi_tasks(task_id, title, owner_agent, status, priority, verification_required, domain) overriding system value values (v_tid, 'rehearsal replay', 'REHEARSAL', 'VERIFICATION', 'P1', true, 'magi');
      insert into public.magi_task_events(event_id, task_id, event_type, actor, detail, payload) overriding system value
        select c_evt_base + 100000000 + t_id * 10000 + row_number() over (order by event_id), v_tid, event_type, actor, 'rehearsal replay', payload
          from public.magi_task_events where task_id = t_id and event_id < c_evt_base order by event_id;
      update public.magi_tasks set status = 'COMPLETED' where task_id = v_tid;
      v_got := (select coalesce(string_agg((payload->>'gate_level') || ':' || (payload->'reasons')::text || '@' || (payload->>'op') || ':' || coalesce(payload->>'from_status', 'null') || '>' || (payload->>'to_status'), ' | ' order by event_id), '(none)') from public.magi_task_events where task_id = v_tid and event_type = 'COMPLETION_GATE_VIOLATION');
      v_want := v_rep_want->>(t_id::text);
      if v_want is null then v_info := v_info || ('replay #' || t_id || ' events=' || v_n || ' -> ' || v_got);
      elsif v_got is not distinct from v_want then n_rep_ok := n_rep_ok + 1; v_log := v_log || ('REPLAY#' || t_id || ':ok');
      else n_rep_drift := n_rep_drift + 1; v_log := v_log || ('REPLAY#' || t_id || ':DRIFT'); v_drift := v_drift || ('REPLAY#' || t_id || ' events=' || v_n || ' got=' || v_got || ' want=' || v_want); end if;
    end loop;

    v_hold_ms := extract(epoch from clock_timestamp() - v_lock_at) * 1000;
    select last_value into v_seq1 from pg_sequences where schemaname = 'public' and sequencename = 'magi_task_events_event_id_seq';
  exception when others then
    v_fatal := sqlstate || ': ' || sqlerrm;
    v_hold_ms := extract(epoch from clock_timestamp() - coalesce(v_lock_at, clock_timestamp())) * 1000;
    select last_value into v_seq1 from pg_sequences where schemaname = 'public' and sequencename = 'magi_task_events_event_id_seq';
  end;

  v_total_ms := extract(epoch from clock_timestamp() - v_t0) * 1000;
  -- UNCONDITIONAL: nothing above can commit; this statement always ends in an error, which rolls the whole statement back.
  raise exception using errcode = 'P0001',
    message = 'REHEARSAL_ROLLBACK_SENTINEL result=' || case when v_fatal <> '' or n_bad > 0 then 'FAIL' when n_rep_drift > 0 then 'PASS_WITH_REPLAY_DRIFT' else 'PASS' end
      || ' checks=' || n_ok || '/' || (n_ok + n_bad) || ' scenarios=' || n_scn_ok || '/' || n_scn || ' replay_ok=' || n_rep_ok || ' replay_drift=' || n_rep_drift
      || ' hold_ms=' || round(coalesce(v_hold_ms, 0)) || ' total_ms=' || round(v_total_ms) || ' max_gate_update_ms=' || round(v_upd_max)
      || ' event_seq_consumed=' || coalesce(v_seq1 - coalesce(v_seq0, 0), -1) || ' gate_sql_md5=' || md5(v_gate)
      || case when v_fatal <> '' then ' FATAL=' || left(v_fatal, 300) else '' end || ' ROLLED_BACK_BY_EXCEPTION',
    detail = array_to_string(v_fail || v_drift || v_info, E'\n') || E'\n' || array_to_string(v_log, ' ');
end $rehearsal$;
